 return {**{k:r[k] for k in ('canonical_method_id','family','method_kind','category','status','source_alias_ids','source_alias_count','reason')},'matching_contract_groups':groups,'source_mapping_proofs':list({json.dumps(m['source_mapping_proof'],sort_keys=True):m['source_mapping_proof'] for m in matches if m['source_mapping_proof']}.values()),'exact_recipe_hashes_retained_in_authority':True,'historical_recipe_equality_claimed':False}
